// spec: specs/edit-listing-save-changes.md (3.7–3.8) · кейс: .qa/tests/edit-listing-save-changes/EDIT-SAVE-09.md · #076449
// Нужно своё объявление: QA_EDIT_LISTING_ID=<id> [QA_EDIT_LISTING_ROLE=user]; без него — skip.
// ПРОД: PATCH business?id=eq.<id> перехватывается и отвечается локально (500, затем 200), на сервер не уходит; прочие не-GET — abort.
import { test, expect, Page } from '@playwright/test';
import { EDIT_ID, EDIT_ROLE, SKIP_REASON, LOAD, SAVE, TITLE_PH, interceptEdit, openEdit } from './edit-listing.helpers';

const ERR_TEXT = 'אירעה שגיאה בשמירת המודעה. הפרטים לא נשמרו, אבל הם עדיין בטופס — נסו שוב.';
const OK_TEXT = 'השינויים נשמרו בהצלחה';

test.use({ storageState: `../auth/${EDIT_ROLE}.json`, serviceWorkers: 'block' });

/** Отметка времени последнего изменения DOM — чтобы считать toast только после окончания анимации, без пауз. */
async function watchDom(page: Page) {
  await page.evaluate(() => {
    const w = window as unknown as { __qaLastMut: number };
    w.__qaLastMut = Date.now();
    new MutationObserver(() => { w.__qaLastMut = Date.now(); })
      .observe(document.body, { subtree: true, childList: true, attributes: true, characterData: true });
  });
}

/** Сколько toast с текстом ошибки видно на экране (ненулевой размер, хотя бы край внутри окна, не прозрачен). */
async function visibleErrorToasts(page: Page): Promise<number | 'settling'> {
  return page.evaluate((t) => {
    const w = window as unknown as { __qaLastMut: number };
    if (Date.now() - w.__qaLastMut < 700) return 'settling';
    const leaves = (Array.from(document.querySelectorAll('body *')) as HTMLElement[]).filter(
      (el) => (el.textContent || '').includes(t) && !Array.from(el.children).some((c) => (c.textContent || '').includes(t)),
    );
    const isShown = (el: HTMLElement) => {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0 || r.bottom <= 0 || r.top >= window.innerHeight) return false;
      for (let e: HTMLElement | null = el; e; e = e.parentElement) {
        const s = getComputedStyle(e);
        if (s.visibility === 'hidden' || s.display === 'none' || Number(s.opacity) < 0.1) return false;
      }
      return true;
    };
    return leaves.filter(isShown).length;
  }, ERR_TEXT);
}

async function failSave(page: Page, n: number) {
  const res = page.waitForResponse((r) => r.request().method() === 'PATCH' && r.url().includes(`id=eq.${EDIT_ID}`), LOAD);
  await page.getByRole('button', { name: SAVE, exact: true }).click();
  expect((await res).status(), `провал ${n}: PATCH получил 500 (перехват)`).toBe(500);
  await expect(page.getByText(ERR_TEXT).first(), `провал ${n}: toast ошибки`).toBeVisible(LOAD);
  // «מה רצוי»: «בכל רגע מוצגת הודעת שגיאה אחת בלבד: הודעה חדשה מחליפה את הקודמת ולא נערמת עליה»
  await expect
    .poll(() => visibleErrorToasts(page), { message: `провал ${n}: на экране ровно один toast ошибки (не стопка)`, timeout: 8_000 })
    .toBe(1);
}

test.describe('Редактирование объявления — повторные провалы сохранения: одна ошибка (#076449)', () => {
  test.skip(!EDIT_ID, SKIP_REASON);

  for (const device of ['@desktop', '@android']) {
    test(`«שמור שינויים» падает 3 раза подряд — на экране одна ошибка, затем успешное сохранение #076449 ${device}`, async ({ page }) => {
      const { patches, passed, state, ctl } = await interceptEdit(page, EDIT_ID);
      await openEdit(page, EDIT_ID, state);
      const title = page.getByPlaceholder(TITLE_PH);
      const newTitle = `QA-AUTO ${(await title.inputValue()).replace(/^QA-AUTO /, '')}`.slice(0, 90);
      await title.fill(newTitle);
      await watchDom(page);

      ctl.patchStatus = 500;
      // второе и третье нажатие — пока предыдущий toast ошибки ещё на экране (сценарий тикета)
      for (let n = 1; n <= 3; n++) await failSave(page, n);
      expect(patches.length, 'каждое нажатие отправило PATCH').toBe(3);
      await expect(page, 'после провалов остаёмся в форме (#775eeb)').toHaveURL(/\/addbusiness\?id=/);
      await expect(title, 'правка на месте').toHaveValue(newTitle);

      // С2 (#917a7d): после провалов успешное сохранение работает
      ctl.patchStatus = 200;
      await page.getByRole('button', { name: SAVE, exact: true }).click();
      await page.waitForURL(/\/mybusinesses/, LOAD);
      await expect(page.getByText(OK_TEXT).first(), `toast «${OK_TEXT}»`).toBeVisible(LOAD);
      expect(Object.values(patches[patches.length - 1].body), 'последний PATCH содержит правку').toContain(newTitle);

      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }
});
